begin;
select no_plan();
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('cc280000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'role','authenticated')::text,true)::void$$;
insert into auth.users(id,email) select pg_temp.id(n),'explainer-'||n||'@test.local' from generate_series(10,15) n;
insert into public.organizations(id,slug,name) values(pg_temp.id(1),'explain-a','A'),(pg_temp.id(2),'explain-b','B');
insert into public.memberships(organization_id,user_id,role) values(pg_temp.id(1),pg_temp.id(10),'owner'),(pg_temp.id(1),pg_temp.id(11),'planner'),(pg_temp.id(1),pg_temp.id(12),'viewer'),(pg_temp.id(1),pg_temp.id(13),'branch_user'),(pg_temp.id(2),pg_temp.id(14),'owner'),(pg_temp.id(1),pg_temp.id(15),'admin');
insert into public.locations(id,organization_id,code,name_en,location_type,country_code,timezone) values(pg_temp.id(20),pg_temp.id(1),'L1','One','branch','SA','Asia/Riyadh'),(pg_temp.id(21),pg_temp.id(1),'L2','Two','branch','SA','Asia/Riyadh');
