reset role; update public.delivery_scenarios set report=(select jsonb_set(report,'{source,lead_time}','null') from original_report) where id=pg_temp.id(97); set local role authenticated; select pg_temp.login(10);
select throws_ok($$select public.delivery_explainer_preview(pg_temp.id(1),pg_temp.id(97))$$,'MQ422',null,'reject missing lead');
