select throws_ok($$select public.delivery_explainer_preview(pg_temp.id(1),pg_temp.id(97))$$,'MQ422',null,'reject missing applicability');
reset role; update public.delivery_scenarios set report=(select jsonb_set(report,'{policy_recalculation_required}','false') from original_report) where id=pg_temp.id(97); set local role authenticated; select pg_temp.login(10);
select throws_ok($$select public.delivery_explainer_preview(pg_temp.id(1),pg_temp.id(97))$$,'MQ422',null,'reject false timing flag');
reset role; update public.delivery_scenarios set report=(select jsonb_set(report,'{order_search,days,0,working}','null') from original_report) where id=pg_temp.id(97); set local role authenticated; select pg_temp.login(10);
select throws_ok($$select public.delivery_explainer_preview(pg_temp.id(1),pg_temp.id(97))$$,'MQ422',null,'reject unknown required day');
